class Policy:
    # Changed: when all tasks in shard are solved, pick the one with highest score below 1.0
    # (most likely to yield a useful proposal) instead of round-robin wasting picks.
    def __init__(self):
        self.scores = {}
        self.counter = 0

    def pick(self, keys, round_index):
        # Filter to unsolved tasks (score < 1.0 or unknown)
        unsolved = [k for k in keys if self.scores.get(k, 0) < 1.0]
        if unsolved:
            # Round-robin among unsolved, but prefer higher-scoring ones (closer to solved)
            # by sorting descending by score, then round-robin within that order
            unsolved.sort(key=lambda k: self.scores.get(k, 0), reverse=True)
            idx = self.counter % len(unsolved)
            self.counter += 1
            return unsolved[idx]
        else:
            # All solved in this shard – pick the one with highest score (most promising)
            # to maximize chance of getting a useful proposal from a near-solved task
            return max(keys, key=lambda k: self.scores.get(k, 0))
