class Policy:
    # Changed: when all tasks in shard are solved, pick the one with highest score below 1.0
    # (most likely to be improvable) instead of round-robin wasting rollouts on solved tasks.
    def __init__(self):
        self.scores = {}
        self.counter = 0

    def pick(self, keys, round_index):
        # Filter to unsolved tasks (score < 1.0 or unknown)
        unsolved = [k for k in keys if self.scores.get(k, 0) < 1.0]
        if not unsolved:
            # All solved in this shard — pick the one with highest score (closest to solved)
            # since it's most likely to be improvable, rather than wasting on solved ones.
            if keys:
                return max(keys, key=lambda k: self.scores.get(k, 0))
            return keys[0]  # fallback (shouldn't happen)
        # Round-robin among unsolved, using a persistent counter
        idx = self.counter % len(unsolved)
        self.counter += 1
        return unsolved[idx]

    def record(self, task_id, score):
        self.scores[task_id] = score
